  Lemma pd_memset : forall (Q : machine_state -> Prop) R1 m RT SF FT HT (retpc spc : Z),
    rfull R1 -> rtbl Wp R1 RT -> ftbl Wp spz m SF -> ftbl Wp ff m FT -> ftbl Wp (ff / 8) m HT -> Pw m -> mem_inv asegs m ->
    as_RFS H ((2, ff, fp) :: LF) m ->
    PropExec.getr R1 10 = Z_to_bv 64 (ff + 32) -> PropExec.getr R1 11 = Z_to_bv 64 0 -> PropExec.getr R1 12 = Z_to_bv 64 16 ->
    PropExec.getr R1 2 = Z_to_bv 64 spc -> PropExec.getr R1 1 = Z_to_bv 64 retpc ->
    spz - 160 <= spc <= spz - 96 -> 0 <= retpc < 2 ^ 64 -> retpc mod 2 = 0 ->
    forallb (fun j => fent_in (SHBASE + 4 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 2) = true ->
    fin (-8192) 0 (fkeys SF) = true -> fin 0 256 (fkeys FT) = true -> fin SHBASE (SHBASE + 32) (fkeys HT) = true ->
    (forall R2 m2, rfull R2 -> rtbl Wp R2 (LbB_DCtorK.keptf RT) -> ftbl Wp spz m2 (fabove (spc - spz) SF) ->
       ftbl Wp ff m2 (fdrop 32 16 FT ++ zents 32 2) -> ftbl Wp (ff / 8) m2 HT -> Pw m2 -> mem_inv asegs m2 ->
       as_RFS H ((2, ff, fp) :: LF) m2 ->
       munch [(ff + 32, ff + 32 + 16); (spc - AINTRIN_STACK, spc)] m m2 -> wmono asegs m m2 ->
       evt asegs Q (MS R2 F (Z_to_bv 64 retpc) fc None m2 (seg_rom asegs))) ->
    evt asegs Q (MS R1 F (Z_to_bv 64 AASAN_MEMSET) fc None m (seg_rom asegs)).
Proof using All.
    intros Q R1 m RT SF FT HT retpc spc RF HRT HSF HFT HHT HP HMI HRFS E10 E11 E12 E2 E1 HSPC HRET HRE2 HZ HSFK HFTK HHTK K.
    pose proof pd_ranges as (G1 & G2 & G3 & G4 & G5 & G6 & G7 & G8 & G9 & G10 & G11 & G12).
    pose proof pd_vals as (V1 & V2 & V3 & V4 & V5).
    pose proof pd_wins as (W1 & W2 & W3 & W4 & W5 & W6 & W7 & W8).
    destruct (pd_keep m HP HMI) as (AC & LV & _ & _ & _ & _ & _ & ST & FW & FV & _ & _).
    pose proof FSB_OK as (_ & _ & _ & FAPP).
    assert (KC : AINTRIN_STACK = 4096 /\ ADS_STACK = 16384 /\ AFS_HDR = 0x9000 /\ AIMG_TOP = 0x6e8000 /\ AAPP_HI = 2 ^ 47)
      by (repeat split; reflexivity).
    destruct KC as (K1 & K2 & K3 & K4 & K5).
    pose proof (Z.div_pos ff 8 ltac:(lia) ltac:(lia)) as Q1.
    pose proof (Z.mul_div_le ff 8 ltac:(lia)) as Q2.
    destruct (stk_split asegs m lo spc spz ST ltac:(lia)) as [STL _].
    assert (WD : wr_at asegs m (ff + 32) 16).
    { destruct FW as (FW0 & FW1 & FWW). split; [lia|]. split; [lia|]. intros i Hi.
      replace (ff + 32 + i) with (ff + (32 + i)) by lia. apply FWW. lia. }
    destruct (rw_cells_of_wr_hi m (ff + 32) 16 WD ltac:(lia) ltac:(lia)) as (junk & CJ).
    assert (D32 : (ff + 32) / 8 = ff / 8 + 4) by (replace (ff + 32) with (ff + 4 * 8) by ring; apply Z.div_add; lia).
    assert (M32 : (ff + 32) mod 8 = 0) by (clear - G6; Z.div_mod_to_equations; lia).
    assert (ADR : addressable m (ff + 32) 16).
    { apply (addr_of_zents Wp (ff / 8) m HT (SHBASE + 4) (ff + 32) 16 HHT HZ); [| lia | exact M32 | lia | reflexivity |].
      - rewrite Z.add_assoc, shb_eq. unfold sh. rewrite D32. ring.
      - unfold sh. rewrite D32. change (16 / 8) with 2. unfold ASHADOW_BASE. lia. }
    assert (ACC : accessible m (ff + 32) 16) by (eapply addressable_accessible; [exact ADR | lia | lia | lia]).
    assert (SHV : shvis m (ff + 32) (ff + 32 + 16)) by (eapply shvis_sub; [exact FV | lia | lia | lia | lia | lia]).
    assert (INM : in_app_mem (ff + 32) (ff + 32 + 16)) by (eapply aapp_in_app_mem; [exact FAPP | lia | lia]).
    assert (AOK : aconst_ok (ff + 32, ff + 32 + 16)) by (eapply LbB_SR.aconst_ok_app; [exact FAPP | lia | lia]).
    eapply evt_cut.
    { eapply (asan_memset_u H HHb R1 F fc m (ff + 32) 16 0 lo junk);
        [exact RF | exact E10 | exact E11 | exact E12 | lia | lia | lia | lia | exact CJ | exact ACC | exact SHV
        | (rewrite E2, unsigned_lit by lia); exact STL | exact CEIL | (rewrite E2, unsigned_lit by lia); lia
        | exact HMI | exact AC | lia | exact INM | exact AOK | left; lia]. }
    intros ms' (R2 & m2 & EQ & RF2 & KEEP & MU & WM & MI2 & AC2 & CB2 & ST2). subst ms'.
    rewrite E2, unsigned_lit in MU by lia.
    rewrite E1, ret_pc_even by (first [exact HRE2 | lia]).
    apply K.
    - exact RF2.
    - exact (rtbl_keep Wp R1 R2 _ _ (LbB_DCtorK.rtbl_keptf Wp R1 RT HRT) (LbB_DCtorK.rsub_keptf RT) KEEP).
    - eapply ftbl_munch; [apply ftbl_fabove; exact HSF | exact MU | exact WM | apply fin_fabove; exact HSFK |].
      cbn [disjoint_from]. split; [lia | split; [lia | exact I]].
    - apply ftbl_app.
      + eapply (ftbl_munch_drop Wp ff m m2 FT [(spc - AINTRIN_STACK, spc)] 0 256 32 16);
          [exact HFT | exact MU | exact WM | exact HFTK | | lia].
        cbn [disjoint_from]. split; [lia | exact I].
      + pose proof (ftbl_zres Wp ff m2 (ff + 32) 16 2 eq_refl CB2) as ZR.
        replace (ff + 32 - ff) with 32 in ZR by ring. exact ZR.
    - eapply ftbl_munch; [exact HHT | exact MU | exact WM | exact HHTK |].
      cbn [disjoint_from]. split; [lia | split; [lia | exact I]].
    - eapply Pw_ext; [exact HP | exact MU | exact WM |].
      apply Forall_cons; [apply in_fr; lia|]. apply Forall_cons; [apply in_stk; lia|]. apply Forall_nil.
    - exact MI2.
    - eapply (ah_RFS_frame H HHb); [exact HRFS | exact MU | exact WM |].
      apply Forall_cons; [apply afs_ok_frame; lia|]. apply Forall_cons; [apply afs_ok_stack; lia|]. apply Forall_nil.
    - exact MU.
    - exact WM.
  Qed.

