  Lemma pd_s28 : (ff + 160) mod 8 = 0.
  Proof.
    pose proof FFR as HF. destruct HF as (_ & _ & _ & (HM & _) & _).
    apply (proj1 (Z.mod_divide ff 64 ltac:(lia))) in HM. destruct HM as [q Hq].
    rewrite Hq. replace (q * 64 + 160) with ((q * 8 + 20) * 8) by ring.
    apply Z.mod_mul. lia.
  Qed.

  Lemma pd_ctor : forall (Q : machine_state -> Prop) R m RT SF FT HT (spc : Z),
    rfull R -> rtbl Wp R RT -> ftbl Wp spz m SF -> ftbl Wp ff m FT -> ftbl Wp (ff / 8) m HT -> Pw m -> mem_inv asegs m ->
    as_RFS H ((2, ff, fp) :: LF) m ->
    PropExec.getr R 10 = Z_to_bv 64 ds -> PropExec.getr R 11 = Z_to_bv 64 (ff + 32) -> PropExec.getr R 12 = Z_to_bv 64 pcons ->
    PropExec.getr R 13 = Z_to_bv 64 (ff + 96) -> PropExec.getr R 14 = Z_to_bv 64 (err mod 2 ^ 64) ->
    PropExec.getr R 15 = Z_to_bv 64 (ff + 160) -> PropExec.getr R 2 = Z_to_bv 64 spc ->
    (spc = spz - 96 \/ spc = spz - 112) ->
    forallb (fun j => fent_in (SHBASE + 32 / 8 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 (Z.to_nat (24 / 8))) = true ->
    forallb (fun j => fent_in (SHBASE + 96 / 8 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 (Z.to_nat (24 / 8))) = true ->
    forallb (fun j => fent_in (SHBASE + 160 / 8 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 (Z.to_nat (24 / 8))) = true ->
    fent_in (32, 8%nat, ELit 0) FT = true -> fent_in (32 + 8, 8%nat, ELit 0) FT = true -> fent_in (32 + 16, 8%nat, EVar 36) FT = true ->
    fent_in (96, 2%nat, ELit 0) FT = true -> fent_in (160, 2%nat, ELit 0) FT = true ->
    fin (-8192) 0 (fkeys SF) = true -> fin 0 256 (fkeys FT) = true -> fin SHBASE (SHBASE + 32) (fkeys HT) = true ->
    (forall R2 m2, rfull R2 -> (forall r, In r KEPT -> PropExec.getr R2 r = PropExec.getr R r) ->
       ftbl Wp spz m2 (fabove (spc - spz) SF) -> ftbl Wp ff m2 FT -> ftbl Wp (ff / 8) m2 HT -> Pw m2 -> mem_inv asegs m2 ->
       as_RFS H ((2, ff, fp) :: LF) m2 -> (forall LB, ds_repA0 LB m2 ds err 0 []) ->
       evt asegs Q (MS R2 F (ret_pc (PropExec.getr R 1)) fc None m2 (seg_rom asegs))) ->
    evt asegs Q (MS R F (Z_to_bv 64 ADS_CTOR) fc None m (seg_rom asegs)).
Proof using All.
    intros Q R m RT SF FT HT spc RF HRT HSF HFT HHT HP HMI HRFS E10 E11 E12 E13 E14 E15 E2 HSPC
           HZ32 HZ96 HZ160 F32 F40 F48 F96 F160 HSFK HFTK HHTK K.
    pose proof pd_ranges as (G1 & G2 & G3 & G4 & G5 & G6 & G7 & G8 & G9 & G10 & G11 & G12).
    pose proof pd_vals as (V1 & V2 & V3 & V4 & V5).
    destruct (pd_keep m HP HMI) as (AC & LV & DA & DW & DV & PA & PCm & ST & FW & FV & _ & _).
    pose proof DSO as (O1 & O2 & O3).
    assert (KC : ADS_STACK = 16384 /\ AIMG_TOP = 0x6e8000 /\ AAPP_HI = 2 ^ 47 /\ DS_SIZE = 392 /\ SHBASE = 0x7fff8000
                 /\ ALOWSH_LO = 0x7fff7000 /\ AHI_LO = 0x10007fff8000 /\ LbB_DCtorK.CT_STACK = 8192)
      by (repeat split; reflexivity).
    destruct KC as (K1 & K2 & K3 & K4 & K5 & K6 & K7 & K8).
    pose proof (Z.div_pos ff 8 ltac:(lia) ltac:(lia)) as Q1.
    pose proof (Z.mul_div_le ff 8 ltac:(lia)) as Q2.
    assert (SPR : spz - 112 <= spc <= spz - 96) by (destruct HSPC as [-> | ->]; lia).
    assert (SPU : bv_unsigned (PropExec.getr R 2) = spc) by (rewrite E2; apply unsigned_lit; lia).
    destruct (fr_app 32 24 ltac:(lia) ltac:(lia) ltac:(lia)) as (PPO & PPH).
    destruct (fr_app 96 24 ltac:(lia) ltac:(lia) ltac:(lia)) as (S1O & S1H).
    destruct (fr_app 160 24 ltac:(lia) ltac:(lia) ltac:(lia)) as (S2O & S2H).
    pose proof (fr_addr m HT 32 HHT HZ32 ltac:(lia) ltac:(lia) eq_refl) as PPA.
    pose proof (fr_addr m HT 96 HHT HZ96 ltac:(lia) ltac:(lia) eq_refl) as S1A.
    pose proof (fr_addr m HT 160 HHT HZ160 ltac:(lia) ltac:(lia) eq_refl) as S2A.
    assert (PPV : shvis m (ff + 32) (ff + 32 + 24)) by (eapply shvis_sub; [exact FV | lia | lia | lia | lia | lia]).
    assert (S1V : shvis m (ff + 96) (ff + 96 + 24)) by (eapply shvis_sub; [exact FV | lia | lia | lia | lia | lia]).
    assert (S2V : shvis m (ff + 160) (ff + 160 + 24)) by (eapply shvis_sub; [exact FV | lia | lia | lia | lia | lia]).
    pose proof (u64arr_of_ents Wp ff m FT 32 (ELit 0) (ELit 0) (EVar 36) HFT F32 F40 F48) as PPC.
    assert (PPL : length [edenot (wenv Wp) (ELit 0); edenot (wenv Wp) (ELit 0); edenot (wenv Wp) (EVar 36)] = 3%nat)
      by reflexivity.
    destruct (fr_str m FT 96 HFT F96 ltac:(lia) ltac:(lia) FW) as (j1 & S1C).
    destruct (fr_str m FT 160 HFT F160 ltac:(lia) ltac:(lia) FW) as (j2 & S2C).
    assert (DJ : forall a, ds <= a < ds + DS_SIZE -> ~ (ff + 32 <= a < ff + 32 + 24) /\ ~ (ff + 96 <= a < ff + 96 + 24)
                   /\ ~ (ff + 160 <= a < ff + 160 + 24) /\ ~ (pcons <= a < pcons + 48)).
    { intros a Ha. pose proof (DISJ a Ha) as Dp. split; [lia | split; [lia | split; [lia | exact Dp]]]. }
    assert (STC : stk asegs m lo (bv_unsigned (PropExec.getr R 2))).
    { rewrite SPU. exact (proj1 (stk_split asegs m lo spc spz ST ltac:(lia))). }
    assert (LOC : lo <= bv_unsigned (PropExec.getr R 2) - LbB_DCtorK.CT_STACK) by (rewrite SPU; lia).
    assert (SPHC : bv_unsigned (PropExec.getr R 2) <= AAPP_HI) by (rewrite SPU; lia).
    pose proof (SPOBJ ds DS_SIZE (or_introl (conj eq_refl eq_refl))) as So1.
    pose proof (SPOBJ pcons 48 (or_intror (conj eq_refl eq_refl))) as So2.
    assert (SPOC : forall O n, O = ds /\ n = DS_SIZE \/ O = ff + 32 /\ n = 24 \/ O = ff + 96 /\ n = 24 \/ O = ff + 160 /\ n = 24
                               \/ O = pcons /\ n = 48 ->
                   O + n <= bv_unsigned (PropExec.getr R 2) - LbB_DCtorK.CT_STACK \/ bv_unsigned (PropExec.getr R 2) <= O).
    { rewrite SPU. intros O n HO. destruct HO as [[-> ->] | [[-> ->] | [[-> ->] | [[-> ->] | [-> ->]]]]]; lia. }
    assert (OHC : forall O n, O = ds /\ n = DS_SIZE \/ O = ff + 32 /\ n = 24 \/ O = ff + 96 /\ n = 24 \/ O = ff + 160 /\ n = 24 ->
                  O + n + 64 <= AAPP_HI).
    { intros O n HO. destruct HO as [[-> ->] | [[-> ->] | [[-> ->] | [-> ->]]]]; assumption. }
    rewrite (MS_full_eq R F _ fc m _ RF).
    eapply evt_cut.
    { pose proof pd_s28 as S28. pose proof HHb as HHr.
      eapply LbB_DCtorR1.ctor_evt with (ds := ds) (ppos := ff + 32) (pcons := pcons) (pstr := ff + 96) (pstr2 := ff + 160)
        (err := err) (lo := lo) (j1 := j1) (j2 := j2) (Hr := H)
        (pos := [edenot (wenv Wp) (ELit 0); edenot (wenv Wp) (ELit 0); edenot (wenv Wp) (EVar 36)]); eassumption. }
    intros ms' HPc.
    destruct HPc as (t0' & t1' & t2' & a0' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & m' & -> & MI' & PW'
                     & REP).
    destruct PW' as (_ & MU & WM). unfold LbB_DCtorK.CW in MU. rewrite SPU in MU.
    apply K.
    - apply rfull_mkR.
    - intros r Hr. apply (getr_mkR_keptR R); [reflexivity | exact Hr].
    - eapply ftbl_munch; [apply ftbl_fabove; exact HSF | exact MU | exact WM | apply fin_fabove; exact HSFK |].
      cbn [disjoint_from]. split; [lia | split; [lia | exact I]].
    - eapply ftbl_munch; [exact HFT | exact MU | exact WM | exact HFTK |].
      cbn [disjoint_from]. split; [lia | split; [lia | exact I]].
    - eapply ftbl_munch; [exact HHT | exact MU | exact WM | exact HHTK |].
      cbn [disjoint_from]. split; [lia | split; [lia | exact I]].
    - eapply Pw_ext; [exact HP | exact MU | exact WM |].
      apply Forall_cons; [apply in_stk; lia|]. apply Forall_cons; [apply in_ds; lia|]. apply Forall_nil.
    - exact MI'.
    - eapply (ah_RFS_frame H HHb); [exact HRFS | exact MU | exact WM |].
      apply Forall_cons; [apply afs_ok_stack; lia|]. apply Forall_cons; [|apply Forall_nil].
      right. destruct DSin as (f & Hf & I1 & I2). exists f. split; [right; exact Hf|]. cbn [fst snd]. lia.
    - exact REP.
  Qed.

  Definition pd_P : machine_state -> Prop :=
    fun ms => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
              F (ret_pc ra) fc None m' (seg_rom asegs)
      /\ mem_inv asegs m' /\ Pw m' /\ as_RFS H LF m' /\ (forall LB, ds_repA0 LB m' ds err 0 []).

  Lemma w4_ds : forall SF FT HT LT ks1 ks2 ks3 ks4 a, 0 <= a < 2 ^ 64 ->
    (ds <= a < ds + DS_SIZE \/ sh ds <= a < sh ds + nsh DS_SIZE) ->
    outside (winsT [tS SF ks1; tF FT ks2; tH HT ks3; tL LT ks4]) a.
Proof.
