  Lemma pd_post : forall R m m4 SF FT HT LT LT0 ks1 ks2 ks3 ks4, rfull R ->
    PropExec.getr R 1 = ra -> PropExec.getr R 2 = sp -> PropExec.getr R 3 = gp -> PropExec.getr R 4 = tp ->
