  Lemma tabs_ok3 : forall m SF FT HT ks1 ks2 ks3, Pw m -> mem_inv asegs m ->
    ftbl Wp spz m SF -> ftbl Wp ff m FT -> ftbl Wp (ff / 8) m HT ->
